users = list_users()
days = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

-- Get all availabilities in parallel
avails = for user in users {
    day_results = for day in days {
        avail = get_availability({ user_id: user.id, date: day })
        return { user_id: user.id, date: day, busy: avail.busy }
    }
    return day_results
}

-- Flatten
flat = fold acc = [] for user_avails in avails {
    return acc + user_avails
}

return flat

