flat = fold acc = [] for user_avails in avails {
    return acc + user_avails
}

candidates = for day in days {
    slots = ["09:00", "09:30", "10:00", "10:30", "11:00", "11:30", "12:00", "12:30", "13:00", "13:30", "14:00", "14:30", "15:00", "15:30", "16:00"]
    day_avails = for entry in flat {
        skip if entry.date != day
        return entry
    }
    for slot in slots {
        slot_end_hour = number.parse(text.slice(slot, 0, 2))
        slot_end_min = number.parse(text.slice(slot, 3, 5)) + 60
        slot_end_hour_final = slot_end_hour + number.floor(slot_end_min / 60)
        slot_end_min_final = slot_end_min % 60
        slot_end = (if slot_end_hour_final < 10 then "0" else "" ) + text.slice("" + slot_end_hour_final, 0, 10) + ":" + (if slot_end_min_final < 10 then "0" else "" ) + text.slice("" + slot_end_min_final, 0, 10)
        skip if slot_end_hour_final > 17 or (slot_end_hour_final == 17 and slot_end_min_final > 0)
        all_free = true
        for entry in day_avails {
            for busy_item in entry.busy {
                conflict = not (slot_end <= busy_item.start or slot >= busy_item.end)
                skip if conflict
            }
            continue
        }
        return { date: day, start: slot, end: slot_end }
    }
}

return candidates
